<?php
require dirname(__DIR__).'/app/bootstrap.php';require_login();require dirname(__DIR__).'/app/layout.php';require dirname(__DIR__).'/app/document-output.php';$id=(int)($_GET['id']??0);$d=document_record($id);$perm=$d['type']==='invoice'?'invoices':'quotations';require_permission($perm.'.view');$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{
 $action=$_POST['action']??'';
 if($action==='issue')issue_document($id);
 elseif($action==='void'){require_permission('invoices.void');transaction(function()use($id){$doc=document_record($id,true);if($doc['type']!=='invoice'||$doc['status']!=='Issued'||scaled($doc['paid'])>0)throw new DomainException('Only an issued invoice with no active payments can be voided. Reverse its payments first.');query("UPDATE documents SET status='Void',version=version+1 WHERE id=? AND business_id=?",[$id,bid()]);audit('invoice.voided','document',$id,['reason'=>required_text('reason',300)]);});}
 elseif($action==='accept'){require_permission('quotations.approve');transaction(function()use($id){$updated=query("UPDATE documents SET status='Accepted',version=version+1 WHERE id=? AND business_id=? AND type='quotation' AND status='Sent'",[$id,bid()]);if($updated->rowCount()!==1)throw new DomainException('Only a sent quotation can be accepted. It may already have changed.');audit('quotation.accepted','document',$id);});}
 elseif($action==='convert'){require_permission('quotations.approve');require_permission('invoices.create');$newId=transaction(function()use($id){$old=document_record($id,true);if($old['type']!=='quotation'||$old['status']!=='Accepted')throw new DomainException('Only an accepted quotation can be converted.');if(scalar('SELECT id FROM documents WHERE source_id=? AND business_id=?',[$id,bid()]))throw new DomainException('This quotation already has an invoice.');$input=rows('SELECT * FROM document_items WHERE document_id=?',[$id]);$new=create_document_nested($old,$input);return $new;});flash('Quotation converted. The original has been preserved.');redirect('invoice-view.php?id='.$newId);}
 elseif($action==='payment')record_payment($id,required_text('amount'),required_text('payment_date'),required_text('method'),(string)($_POST['reference']??''),(string)($_POST['submission_key']??''));
 else throw new DomainException('Unknown document action.');
 flash('Your changes have been saved.');redirect('invoice-view.php?id='.$id);
 }catch(DomainException $ex){$error=$ex->getMessage();}}
$d=document_record($id);$items=rows('SELECT * FROM document_items WHERE document_id=?',[$id]);$actions='';if(can($perm.'.print'))$actions='<button class="btn" data-print>'.icon('printer').' Print</button>';if(can($perm.'.export'))$actions.='<a class="btn primary" href="download.php?type=document&id='.$id.'">'.icon('download').' Download PDF</a>';page_start($d['number'],$d['type']==='invoice'?'A complete record of your work and payments.':'A thoughtful proposal for your next opportunity.',$actions);error_notice($error);
?><div class="invoice-layout"><article class="panel invoice-paper"><?= document_markup($d,$items) ?></article><aside class="panel invoice-side"><h3>Document actions</h3><?php if($d['status']==='Draft'&&can($perm.'.issue')): ?><p class="muted">Review the details before issuing. Issued documents preserve a snapshot of your business and customer.</p><form method="post" data-confirm="Issue this document? Its details will be preserved and cannot be silently overwritten."><?php csrf_field(); ?><input type="hidden" name="action" value="issue"><button class="btn primary">Issue <?= e($d['type']) ?></button></form><?php endif; ?><?php if($d['type']==='quotation'&&$d['status']==='Sent'&&can('quotations.approve')): ?><form method="post"><?php csrf_field(); ?><input type="hidden" name="action" value="accept"><button class="btn primary">Mark as accepted</button></form><?php endif; ?><?php if($d['type']==='quotation'&&$d['status']==='Accepted'&&can('invoices.create')): ?><form method="post"><?php csrf_field(); ?><input type="hidden" name="action" value="convert"><button class="btn primary">Convert to invoice draft</button></form><?php endif; ?><?php if($d['type']==='invoice'&&$d['status']==='Issued'&&scaled($d['total'])>scaled($d['paid'])&&can('payments.record')): ?><h3>Record a payment</h3><form method="post"><?php csrf_field(); ?><input type="hidden" name="action" value="payment"><input type="hidden" name="submission_key" value="<?= bin2hex(random_bytes(32)) ?>"><?php field('amount',['Amount (₹)','number',true],decimal(scaled($d['total'])-scaled($d['paid'])));field('payment_date',['Payment date','date',true],date('Y-m-d'));field('method',['Payment method',['Bank transfer','UPI','Cash','Card','Cheque','Other']]);field('reference',['Reference','text']); ?><button class="btn primary"><?= icon('plus') ?> Record payment</button></form><?php endif; ?><?php if($d['type']==='invoice'&&$d['status']==='Issued'&&scaled($d['paid'])===0&&can('invoices.void')): ?><h3>Void invoice</h3><form method="post" data-confirm="Void this invoice? It will be excluded from revenue and retained in history."><?php csrf_field(); ?><input type="hidden" name="action" value="void"><?php field('reason',['Reason','text',true]); ?><button class="btn danger">Void invoice</button></form><?php endif; ?><a class="btn" href="<?= $perm ?>.php"><?= icon('arrow-left') ?> Back to <?= $perm ?></a></aside></div><?php page_end(); ?>
